 public @org.jetbrains.annotations.NotNull CompletableFuture<Customer> createCustomer(CustomerInput body) { return call("createCustomer", new String[]{}, body, Collections.emptyMap(), null, Collections.emptyMap(), Customer.class); }
 public @org.jetbrains.annotations.NotNull CompletableFuture<CustomerPage> listCustomers(@org.jetbrains.annotations.Nullable String after, long limit, @org.jetbrains.annotations.Nullable String q) { return call("listCustomers", new String[]{}, null, query("after", after, "limit", limit, "q", q), null, Collections.emptyMap(), CustomerPage.class); }
